"""Markdown templates for meeting notes."""

MEETING_NOTES_TEMPLATE = """# {title}

**Date:** {date}
**Duration:** {duration}
**Speakers:** {speakers}
{meeting_type_line}

---

## Summary

{summary}

---

## Key Points

{key_points}

---

## Action Items

{action_items_section}

---

## Decisions Made

{decisions_section}

---

## Full Transcript

<details>
<summary>Click to expand transcript</summary>

{transcript}

</details>

---

*Generated by Zoom Notes Taker on {generation_date}*
"""

SIMPLE_NOTES_TEMPLATE = """# {title}

**Date:** {date}
**Duration:** {duration}

---

## Summary

{summary}

---

## Key Points

{key_points}

---

## Transcript

{transcript}

---

*Generated by Zoom Notes Taker*
"""


def format_key_points(points: list[str]) -> str:
    """Format key points as a markdown list."""
    if not points:
        return "- No key points extracted"
    return "\n".join(f"- {point}" for point in points)


def format_action_items(items: list) -> str:
    """Format action items as a markdown table."""
    if not items:
        return "No action items identified."

    lines = [
        "| Task | Assigned To | Due Date |",
        "|------|-------------|----------|",
    ]

    for item in items:
        assignee = getattr(item, "assignee", None) or getattr(item, "description", "-")
        if hasattr(item, "description"):
            task = item.description
            assignee = item.assignee or "-"
        else:
            task = getattr(item, "task", str(item))
            assignee = getattr(item, "assignee", "-") or "-"

        due = getattr(item, "due_date", None) or getattr(item, "deadline", None) or "-"
        lines.append(f"| {task} | {assignee} | {due} |")

    return "\n".join(lines)


def format_decisions(decisions: list) -> str:
    """Format decisions as markdown."""
    if not decisions:
        return "No decisions recorded."

    lines = []
    for i, decision in enumerate(decisions, 1):
        if hasattr(decision, "description"):
            desc = decision.description
            rationale = decision.rationale
            stakeholders = decision.stakeholders
        else:
            desc = getattr(decision, "decision", str(decision))
            rationale = getattr(decision, "rationale", None)
            stakeholders = getattr(decision, "stakeholders", [])

        lines.append(f"### Decision {i}")
        lines.append(f"- **Decision:** {desc}")
        if rationale:
            lines.append(f"- **Rationale:** {rationale}")
        if stakeholders:
            lines.append(f"- **Stakeholders:** {', '.join(stakeholders)}")
        lines.append("")

    return "\n".join(lines)


def format_speakers(speakers: list) -> str:
    """Format speaker list."""
    if not speakers:
        return "Unknown"

    labels = []
    for speaker in speakers:
        if hasattr(speaker, "display_name"):
            labels.append(speaker.display_name)
        elif hasattr(speaker, "label"):
            labels.append(speaker.label)
        else:
            labels.append(str(speaker))

    return ", ".join(labels)


def render_meeting_notes(notes) -> str:
    """
    Render MeetingNotes to markdown.

    Args:
        notes: MeetingNotes object

    Returns:
        Formatted markdown string
    """
    from datetime import datetime

    # Format meeting type line
    meeting_type_line = ""
    if hasattr(notes, "meeting_type") and notes.meeting_type != "other":
        meeting_type_line = f"**Type:** {notes.meeting_type.title()}"

    # Format components
    key_points = format_key_points(notes.key_points)
    action_items_section = format_action_items(notes.action_items)
    decisions_section = format_decisions(notes.decisions)
    speakers = format_speakers(notes.speakers) if notes.speakers else "Unknown"

    # Get transcript
    if hasattr(notes, "formatted_transcript"):
        transcript = notes.formatted_transcript
    elif hasattr(notes, "transcript_segments"):
        lines = []
        for seg in notes.transcript_segments:
            speaker = getattr(seg, "speaker_label", "Unknown")
            timestamp = getattr(seg, "timestamp", "")
            lines.append(f"{timestamp} **{speaker}:** {seg.text}")
        transcript = "\n".join(lines)
    else:
        transcript = notes.full_transcript if hasattr(notes, "full_transcript") else ""

    if not transcript:
        transcript = "No transcript available."

    # Format dates
    if hasattr(notes, "formatted_date"):
        date_str = notes.formatted_date
    else:
        date_str = notes.date.strftime("%B %d, %Y at %H:%M")

    if hasattr(notes, "formatted_duration"):
        duration_str = notes.formatted_duration
    else:
        duration_str = f"{int(notes.duration_minutes)} minutes"

    generation_date = datetime.now().strftime("%Y-%m-%d %H:%M")

    return MEETING_NOTES_TEMPLATE.format(
        title=notes.title,
        date=date_str,
        duration=duration_str,
        speakers=speakers,
        meeting_type_line=meeting_type_line,
        summary=notes.summary or "No summary available.",
        key_points=key_points,
        action_items_section=action_items_section,
        decisions_section=decisions_section,
        transcript=transcript,
        generation_date=generation_date,
    )


def render_simple_notes(title: str, date: datetime, duration: float, summary: str, key_points: list[str], transcript: str) -> str:
    """Render simple meeting notes without full structure."""
    from datetime import datetime as dt

    return SIMPLE_NOTES_TEMPLATE.format(
        title=title,
        date=date.strftime("%B %d, %Y at %H:%M"),
        duration=f"{int(duration)} minutes",
        summary=summary or "No summary available.",
        key_points=format_key_points(key_points),
        transcript=transcript or "No transcript available.",
    )
